/// Adds the route of contract `load-counters` to `routes`, answered by `handler` after the checks the specification states for it.
pub fn serve_load_counters<A, S, H>(
    routes: strata_runtime::Routes<A>,
    handler: std::sync::Arc<S>,
    hooks: std::sync::Arc<H>,
) -> strata_runtime::Routes<A>
where
    A: strata_runtime::Authorizer,
    S: LoadCountersHandler,
    H: LoadCountersHooks,
{
    routes.serve_checked::<LoadCounters, _, _>(
        move |caller: strata_runtime::Caller, request: crate::contracts::LoadCountersRequest| {
            let (handler, hooks) = (handler.clone(), hooks.clone());
            async move { answer_load_counters(&*handler, &*hooks, caller, request).await }
        },
    )
}

