/// What the routes of component `store` (Store) need from the deployment beyond the implementation of its contracts: the hooks of every one of them.
pub trait StoreHooks: LoadCountersHooks + CommitBumpHooks + MutateCounterHooks {}

impl<T: LoadCountersHooks + CommitBumpHooks + MutateCounterHooks> StoreHooks for T {}

/// Adds the route of every contract component `store` implements to `routes`, each answered by `service` after the checks the specification states for it.
pub fn store_routes<A, S, H>(
    routes: strata_runtime::Routes<A>,
    service: std::sync::Arc<S>,
    hooks: std::sync::Arc<H>,
) -> strata_runtime::Routes<A>
where
    A: strata_runtime::Authorizer,
    S: crate::contracts::Store + Send + Sync + 'static,
    H: StoreHooks,
{
    let routes = serve_load_counters(routes, service.clone(), hooks.clone());
    let routes = serve_commit_bump(routes, service.clone(), hooks.clone());
    serve_mutate_counter(routes, service, hooks)
}

